import app from 'flarum/forum/app';
import Hero from 'flarum/forum/components/Hero';
import Icon from 'flarum/common/components/Icon';
import textContrastClass from 'flarum/common/helpers/textContrastClass';
import classList from 'flarum/common/utils/classList';
import ItemList from 'flarum/common/utils/ItemList';
export default class UserDirectoryHero extends Hero {
  className() {
    const color = this.heroColor();
    return classList('UserDirectoryHero', {
      'UserDirectoryHero--colored': color,
      [textContrastClass(color)]: color
    });
  }
  style() {
    const color = this.heroColor();
    return color ? {
      '--hero-bg': color
    } : undefined;
  }
  bodyItems() {
    const items = new ItemList();
    items.add('content', m("div", {
      className: "containerNarrow"
    }, this.contentItems().toArray()), 80);
    return items;
  }
  contentItems() {
    const items = new ItemList();
    items.add('user-directory-title', m("h1", {
      className: "Hero-title"
    }, m(Icon, {
      name: this.heroIcon()
    }), " ", app.translator.trans('fof-user-directory.forum.hero.title')), 100);
    return items;
  }

  /**
   * A colour for the hero background, or null for the theme's default.
   */
  heroColor() {
    return null;
  }
  heroIcon() {
    return 'far fa-address-book';
  }
}
flarum.reg.add('fof-user-directory', 'forum/components/UserDirectoryHero', UserDirectoryHero);